    @Test
    public void vignetting_factors() {
        var fields = build().optical_spec.fov.fields;
        assertClose("fld.0.vlx", -3.278333220664287E-4d, fields[0].vlx, 1.0e-6);
        assertClose("fld.0.vly", -3.278333220664287E-4d, fields[0].vly, 1.0e-6);
        assertClose("fld.0.vux", -3.278333220664287E-4d, fields[0].vux, 1.0e-6);
        assertClose("fld.0.vuy", -3.278333220664287E-4d, fields[0].vuy, 1.0e-6);
        assertClose("fld.1.vlx", 0.10129921028052569d, fields[1].vlx, 1.0e-6);
        assertClose("fld.1.vly", 0.4630981116240167d, fields[1].vly, 1.0e-6);
        assertClose("fld.1.vux", 0.10129921028052569d, fields[1].vux, 1.0e-6);
        assertClose("fld.1.vuy", 0.2611450268063015d, fields[1].vuy, 1.0e-6);
        assertClose("fld.2.vlx", 0.31366309882068544d, fields[2].vlx, 1.0e-6);
        assertClose("fld.2.vly", 0.7587794554974773d, fields[2].vly, 1.0e-6);
        assertClose("fld.2.vux", 0.31366309882068544d, fields[2].vux, 1.0e-6);
        assertClose("fld.2.vuy", 0.5046433195452281d, fields[2].vuy, 1.0e-6);
    }

    @Test
    public void chief_ray_aiming() {
        var fields = build().optical_spec.fov.fields;
        Assertions.assertNotNull(fields[0].aim_info, "aim.0.x - expected paraxial aiming");
        assertClose("aim.0.x", 0.0d, fields[0].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[0].aim_info, "aim.0.y - expected paraxial aiming");
        assertClose("aim.0.y", 0.0d, fields[0].aim_info[1], 1.0e-6);
        Assertions.assertNotNull(fields[1].aim_info, "aim.1.x - expected paraxial aiming");
        assertClose("aim.1.x", 0.0d, fields[1].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[1].aim_info, "aim.1.y - expected paraxial aiming");
        assertClose("aim.1.y", -0.26951538880208303d, fields[1].aim_info[1], 1.0e-6);
        Assertions.assertNotNull(fields[2].aim_info, "aim.2.x - expected paraxial aiming");
        assertClose("aim.2.x", 0.0d, fields[2].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[2].aim_info, "aim.2.y - expected paraxial aiming");
        assertClose("aim.2.y", -0.8656857850402943d, fields[2].aim_info[1], 1.0e-6);
    }

