        assertClose("ray.0.1.2.dst", 3.023805779672447d, s2.dst, 1.0e-6);
        var s3 = pkg.ray.get(3);
        assertClose("ray.0.1.3.p.x", 0.0d, s3.p.x, 1.0e-6);
        assertClose("ray.0.1.3.p.y", 19.450961312819082d, s3.p.y, 1.0e-6);
        assertClose("ray.0.1.3.p.z", 1.5847410166383744d, s3.p.z, 1.0e-6);
        assertClose("ray.0.1.3.d.x", 0.0d, s3.d.x, 1.0e-6);
